  "svm.cmp.err": "Errores",
  "svm.cmp.obj": "Objetivo",
  "svm.cmp.note": "De C = {c0} a C = {c1} la calle se angosta de {w0} a {w1}, los lotes con ξ > 0 bajan de {v0} a {v1} y los errores de entrenamiento de {e0} a {e1}. Ningún valor de C recupera la calle de los primeros lotes ({hw}): con el lote atípico, siempre queda algún lote del lado equivocado.",

  "svm.lots.kicker": "Cada lote",
  "svm.lots.title": "{n} lotes con C = {c}",
  "svm.lots.p": "Ordenados por y f(x), la distancia a la frontera en unidades de 1/‖w‖, con signo: por debajo de 0 el lote está del lado equivocado, entre 0 y 1 está dentro de la calle, y 1 lo pone en un borde. ξ = máx(0, 1 − y f(x)) es su holgura y α su multiplicador dual, entre 0 y C = {c}. El lote {n}* es el atípico.",
  "svm.lots.alt": "Altitud (m)",
  "svm.lots.den": "Densidad (g/L)",
